# ---------- ✨ Animatsiyali (custom) emojilar — Bot Creator inline tugmalari uchun ----------
def _anim_norm(s: str) -> str:
    """Emoji variatsiya belgisini (U+FE0F) olib tashlaydi — solishtirish uchun."""
    return (s or "").replace("\ufe0f", "")


def _anim_strip_lead(text: str, key: str):
    """text `key` emoji bilan boshlansa, emojisiz qolgan matnni qaytaradi, aks holda None."""
    nk = _anim_norm(key)
    if not nk:
        return None
    i = j = 0
    while j < len(nk) and i < len(text):
        if text[i] == "\ufe0f":
            i += 1
            continue
        if text[i] == nk[j]:
            i += 1
            j += 1
        else:
            return None
    if j < len(nk):
        return None
    while i < len(text) and text[i] == "\ufe0f":
        i += 1
    return text[i:].strip()


def anim_active() -> bool:
    return bool(data.get("anim_enabled")) and bool(data.get("anim_emojis"))


def anim_transform_markup(markup):
    """Inline tugma matnining boshidagi oddiy emojini animatsiyali (custom) emoji ikonkasiga almashtiradi.
    O'zgarish bo'lmasa None qaytaradi."""
    emojis = data.get("anim_emojis") or {}
    keys = sorted(emojis, key=len, reverse=True)
    changed = False
    rows = []
    for row in markup.inline_keyboard:
        new_row = []
        for b in row:
            nb = b
            if not getattr(b, "icon_custom_emoji_id", None):
                for k in keys:
                    rest = _anim_strip_lead(b.text or "", k)
                    if rest is not None:
                        if rest:
                            nb = b.model_copy(update={"text": rest, "icon_custom_emoji_id": emojis[k]})
                            changed = True
                        break
            new_row.append(nb)
        rows.append(new_row)
    return markup.model_copy(update={"inline_keyboard": rows}) if changed else None


def anim_transform_reply(markup):
    """Pastdagi doimiy menyu tugmalarida matn boshidagi oddiy emojini premium ikonkaga almashtiradi.
    Tugma bosilganda Telegram emojisiz matn yuboradi — uni ReplyLabelRestoreMiddleware asl holiga qaytaradi
    (shuning uchun «emojisiz matn -> asl matn» ro'yxati bazada saqlanadi). Noaniq (ikki xil asl matnga mos) tugmalarga tegilmaydi."""
    emojis = data.get("anim_emojis") or {}
    keys = sorted(emojis, key=len, reverse=True)
    lmap = data.setdefault("reply_label_map", {})
    changed = False
    new_entry = False
    rows = []
    for row in markup.keyboard:
        new_row = []
        for b in row:
            nb = b
            if not isinstance(b, str) and getattr(b, "text", None) and not getattr(b, "icon_custom_emoji_id", None):
                for k in keys:
                    rest = _anim_strip_lead(b.text, k)
                    if rest is not None:
                        if rest and lmap.get(rest, b.text) == b.text:
                            if rest not in lmap:
                                lmap[rest] = b.text
                                new_entry = True
                            nb = b.model_copy(update={"text": rest, "icon_custom_emoji_id": emojis[k]})
                            changed = True
                        break
            new_row.append(nb)
        rows.append(new_row)
    if new_entry:
        try:
            save_data()
        except Exception as e:
            logging.info(f"reply_label_map saqlanmadi: {e}")
    return markup.model_copy(update={"keyboard": rows}) if changed else None


class ReplyLabelRestoreMiddleware(BaseMiddleware):
    """Premium ikonkali menyu tugmasi bosilganda kelgan emojisiz matnni asl matnga (emoji bilan) qaytaradi,
    shunda hozirgi F.text == "🤖 Botlarim" kabi handlerlar o'zgarishsiz ishlayveradi."""
    async def __call__(self, handler, event, mw_data):
        try:
            txt = getattr(event, "text", None)
            if txt and isinstance(event, Message):
                orig = (data.get("reply_label_map") or {}).get(txt)
                if orig and orig != txt:
                    event = event.model_copy(update={"text": orig})
        except Exception as e:
            logging.info(f"Menyu matnini tiklashda xato (e'tiborsiz): {e}")
        return await handler(event, mw_data)


def install_reply_label_restore(dp):
    dp.message.outer_middleware(ReplyLabelRestoreMiddleware())


async def anim_fetch_flags(bot, ids: list) -> dict:
    """{custom_emoji_id: animatsiyali_mi} — Telegram'dan so'raydi. Aniqlab bo'lmaganlar lug'atda bo'lmaydi."""
    flags = {}
    ids = list(dict.fromkeys(ids))
    for i in range(0, len(ids), 200):
        try:
            res = await bot.get_custom_emoji_stickers(custom_emoji_ids=ids[i:i + 200])
        except Exception as e:
            logging.info(f"Emoji turini aniqlashda xato: {e}")
            continue
        for st in res:
            if st.custom_emoji_id:
                flags[st.custom_emoji_id] = bool(getattr(st, "is_animated", False) or getattr(st, "is_video", False))
    return flags


_ANIM_SKIP_TAGS = ("tg-emoji", "code", "pre", "a")


def anim_transform_text(text: str):
    """HTML matndagi saqlangan oddiy emojilarni <tg-emoji> (animatsiyali) bilan almashtiradi.
    <code>, <pre>, <a> va mavjud <tg-emoji> ichiga tegmaydi. O'zgarish bo'lmasa None."""
    emojis = data.get("anim_emojis") or {}
    if not text or not emojis:
        return None
    keys = sorted(emojis, key=len, reverse=True)
    pat = re.compile("(" + "|".join(re.escape(k) for k in keys) + ")\ufe0f?")
    changed = 0
    skip = 0
    out = []

    def sub(m):
        nonlocal changed
        if changed >= 90:          # Telegram chegarasi — xabarda 100 tagacha custom emoji
            return m.group(0)
        changed += 1
        return f'<tg-emoji emoji-id="{emojis[m.group(1)]}">{m.group(0)}</tg-emoji>'

    for part in re.split(r"(<[^>]*>)", text):
        if len(part) > 2 and part.startswith("<") and part.endswith(">"):
            m = re.match(r"</?\s*([A-Za-z0-9\-]+)", part)
            if m and m.group(1).lower() in _ANIM_SKIP_TAGS:
                if part.startswith("</"):
                    skip = max(0, skip - 1)
                elif not part.endswith("/>"):
                    skip += 1
            out.append(part)
        elif skip or not part:
            out.append(part)
        else:
            out.append(pat.sub(sub, part))
    return "".join(out) if changed else None


def _btn_key(text: str) -> str:
    return _anim_norm(text or "").strip()


def btn_hash(text: str) -> str:
    return hashlib.md5(_btn_key(text).encode("utf-8")).hexdigest()[:10]


_BTN_NUM_RE = re.compile(r"\d+(?:[ ,.\u00a0]\d+)*")


def _btn_norm(text: str) -> str:
    """Narx/son o'zgarsa ham rang saqlansin: raqamlar '#' bilan almashtiriladi."""
    return _BTN_NUM_RE.sub("#", _btn_key(text))


_btn_last_save = 0.0


def _btn_seen_add(key: str, seen: list):
    """Tugmani 'ko'rilgan' ro'yxatiga qo'shadi (har 2 daqiqada ko'pi bilan bir marta bazaga yoziladi)."""
    global _btn_last_save
    if not key or key in seen:
        return
    seen.insert(0, key)
    now = datetime.now().timestamp()
    if now - _btn_last_save > 120:
        _btn_last_save = now
        try:
            save_data()
        except Exception as e:
            logging.info(f"btn_seen saqlanmadi: {e}")


def _btn_style_for(key: str, colors: dict):
    if not key or not colors:
        return None
    style = colors.get(key)
    if style:
        return style
    nk = _btn_norm(key)
    for ck, cv in colors.items():
        if _btn_norm(ck) == nk:
            return cv
    return None


# ---------- 🎨 Avtomatik tugma ranglari (qoidalar) ----------
# 🔴 qizil  : Orqaga / O'chirish tugmalari
# 🟢 yashil : Faol va Botlar tugmalari
# 🔵 ko'k   : Qoida va shunga o'xshash (Shartlar, Yordam, Qo'llanma, Ma'lumot) hamda veb-sahifaga o'tkazuvchi tugmalar
# Admin qo'lda (🎨 Ranglar / 🎨 Dizayn) rang bergan tugma esa o'z rangini saqlaydi.
AUTO_DEFAULT_STYLE = "primary"   # hech qaysi qoidaga tushmagan HAR BIR tugma ko'k bo'ladi
_AUTO_APOS = str.maketrans({"\u02bb": "'", "\u02bc": "'", "\u2019": "'", "\u2018": "'", "`": "'", "\u00b4": "'"})
_AUTO_RED_RE = re.compile(r"(orqaga|ortga|\bback\b|o'chir|ochir|\bdelete\b|\U0001F5D1)")
_AUTO_GREEN_RE = re.compile(r"((?<![a-z])faol|botlar)")
_AUTO_BLUE_RE = re.compile(r"(qoida|shartlar|yordam|qo'llanma|ma'lumot|haqida|\U0001F4DC)")
_AUTO_BACK_ARROWS = ("\u2b05", "\u25c0", "\u23ea", "\U0001F519", "\u21a9", "\u2190")


def auto_btn_style(b):
    """Tugma matni/turiga qarab avtomatik rang: 'danger' (qizil), 'success' (yashil), 'primary' (ko'k) yoki None."""
    try:
        t = _anim_norm((getattr(b, "text", "") or "").translate(_AUTO_APOS).lower()).strip()
        if not t:
            return None
        if _AUTO_RED_RE.search(t):
            return "danger"
        if t.startswith(_AUTO_BACK_ARROWS) and len(t.lstrip("".join(_AUTO_BACK_ARROWS) + " ")) >= 3:
            return "danger"            # «⬅️ Bosh menyu» kabi orqaga tugmalari (faqat «◀️» sahifalash tugmasi emas)
        if _AUTO_GREEN_RE.search(t):
            return "success"
        if _AUTO_BLUE_RE.search(t):
            return "primary"
        if getattr(b, "web_app", None) or getattr(b, "url", None) or getattr(b, "login_url", None):
            return "primary"           # veb-sahifaga / mini-ilovaga o'tkazuvchi tugmalar
    except Exception:
        pass
    return None


def auto_style_markup(mk):
    """Faqat avtomatik qoidalar bo'yicha rang beradi (qo'lda rang yo'q botlar uchun). O'zgarish bo'lmasa None."""
    changed = False

    def one(b):
        nonlocal changed
        if getattr(b, "style", None):
            return b
        st = auto_btn_style(b) or AUTO_DEFAULT_STYLE
        if st:
            changed = True
            return b.model_copy(update={"style": st})
        return b

    if isinstance(mk, InlineKeyboardMarkup):
        rows = [[one(b) for b in row] for row in mk.inline_keyboard]
        return mk.model_copy(update={"inline_keyboard": rows}) if changed else None
    if isinstance(mk, ReplyKeyboardMarkup):
        rows = [[one(b) for b in row] for row in mk.keyboard]
        return mk.model_copy(update={"keyboard": rows}) if changed else None
    return None


def btn_record_and_style(markup):
    """Bot yuborgan inline tugmalarni ro'yxatga oladi va sozlangan ranglarni (style) qo'llaydi.
    O'zgarish bo'lmasa None qaytaradi."""
    colors = data.get("btn_colors") or {}
    seen = data.setdefault("btn_seen", [])
    changed = False
    rows = []
    for row in markup.inline_keyboard:
        new_row = []
        for b in row:
            nb = b
            key = _btn_key(b.text)
            cbd = str(getattr(b, "callback_data", "") or "")
            if key and not cbd.startswith(("clr_", "txt_")):
                _btn_seen_add(key, seen)
            style = _btn_style_for(key, colors) or auto_btn_style(b) or AUTO_DEFAULT_STYLE
            if style and not getattr(b, "style", None):
                nb = b.model_copy(update={"style": style})
                changed = True
            new_row.append(nb)
        rows.append(new_row)
    del seen[300:]
    return markup.model_copy(update={"inline_keyboard": rows}) if changed else None


def btn_record_and_style_reply(markup):
    """Pastdagi doimiy (reply) klaviatura tugmalarini ham ro'yxatga oladi va ranglaydi."""
    colors = data.get("btn_colors") or {}
    seen = data.setdefault("btn_seen", [])
    changed = False
    rows = []
    for row in markup.keyboard:
        new_row = []
        for b in row:
            nb = b
            text = getattr(b, "text", None)
            if text:
                key = _btn_key(text)
                _btn_seen_add(key, seen)
                style = _btn_style_for(key, colors) or auto_btn_style(b) or AUTO_DEFAULT_STYLE
                if style and not getattr(b, "style", None):
                    nb = b.model_copy(update={"style": style})
                    changed = True
            new_row.append(nb)
        rows.append(new_row)
    del seen[300:]
    return markup.model_copy(update={"keyboard": rows}) if changed else None


_anim_off_until = 0.0     # animatsiyali emoji rad etilsa, shu vaqtgacha (timestamp) faqat ranglar ishlatiladi
_anim_status = {"ok": None, "err": "", "ts": 0.0}   # oxirgi urinish natijasi (✨ Animatsiya panelida ko'rinadi)


async def anim_request_middleware(make_request, bot, method):
    """Bot Creator xabarlariga tugma ranglari (🎨) va animatsiyali emoji (✨) qo'shadi.
    Telegram rad etsa, bosqichma-bosqich soddalashtiradi: (ranglar + emoji) → (faqat ranglar) → asl xabar.
    Shunda animatsiyali emoji ishlamasa (masalan, bot egasida Premium yo'q), ranglar baribir ishlaydi."""
    global _anim_off_until
    try:
        method = autotext_apply(method)
    except Exception as e:
        logging.info(f"Avto-matn almashtirishda xato (e'tiborsiz): {e}")
    full = style_only = None
    try:
        mk = getattr(method, "reply_markup", None)
        if isinstance(mk, InlineKeyboardMarkup):
            styled_mk = btn_record_and_style(mk)
        elif isinstance(mk, ReplyKeyboardMarkup):
            styled_mk = btn_record_and_style_reply(mk)
        else:
            styled_mk = None
        base_mk = styled_mk if styled_mk is not None else mk
        style_updates = {"reply_markup": styled_mk} if styled_mk is not None else {}
        if style_updates:
            style_only = method.model_copy(update=style_updates)
        anim_updates = {}
        if anim_active() and datetime.now().timestamp() >= _anim_off_until:
            if isinstance(base_mk, InlineKeyboardMarkup):
                am = anim_transform_markup(base_mk)
                if am is not None:
                    anim_updates["reply_markup"] = am
            elif isinstance(base_mk, ReplyKeyboardMarkup):
                am = anim_transform_reply(base_mk)
                if am is not None:
                    anim_updates["reply_markup"] = am
            if hasattr(method, "parse_mode") and not getattr(method, "entities", None) and not getattr(method, "caption_entities", None):
                pm = getattr(method, "parse_mode", None)
                if (isinstance(pm, str) and pm.upper() == "HTML") or (pm is not None and not isinstance(pm, str)):
                    for field in ("text", "caption"):
                        val = getattr(method, field, None)
                        if isinstance(val, str):
                            nv = anim_transform_text(val)
                            if nv is not None:
                                anim_updates[field] = nv
        if anim_updates:
            full = method.model_copy(update={**style_updates, **anim_updates})
    except Exception as e:
        logging.info(f"Tugma/emoji bezashda xato (e'tiborsiz): {e}")
        full = style_only = None
    for m in (full, style_only):
        if m is None:
            continue
        try:
            res = await make_request(bot, m)
            if m is full:
                _anim_status.update(ok=True, err="", ts=datetime.now().timestamp())
            if m is style_only and full is not None:
                _anim_off_until = datetime.now().timestamp() + 120
                logging.warning("Animatsiyali emoji qabul qilinmadi (bot egasida Premium bo'lmasligi mumkin) — 2 daqiqa faqat ranglar ishlatiladi")
            return res
        except TelegramBadRequest as e:
            if "not modified" in str(e).lower():
                raise
            if m is full:
                _anim_status.update(ok=False, err=str(e)[:300], ts=datetime.now().timestamp())
            logging.warning(f"Bezatilgan xabar qabul qilinmadi, soddaroq ko'rinishda yuborilmoqda: {e}")
    return await make_request(bot, method)


