def available_bot_types() -> dict:
    """Foydalanuvchilarga ko'rinadigan bot turlari: menyuga qo'shilgan VA yoqilgan turlar."""
    result = {}
    for bt in BOT_TYPES:
        entry = data["bot_menu"].get(bt)
        if entry and entry.get("enabled", True) and bt not in MENU_HIDDEN_TYPES:
            result[bt] = entry.get("name") or BOT_TYPES[bt]
    return result


def is_type_available(bot_type: str) -> bool:
    return bot_type in available_bot_types()

