BALANCE_LOG_LIMIT = 100


def log_balance(uid, delta: int, reason: str):
    """Balans o'zgarishini tarixga yozadi (har bir foydalanuvchi uchun oxirgi 100 ta). save_data() ni chaqiruvchi bajaradi."""
    try:
        key = str(uid)
        lst = data.setdefault("balance_log", {}).setdefault(key, [])
        lst.append({
            "t": datetime.now().isoformat(timespec="seconds"),
            "d": int(delta),
            "r": reason,
            "b": data["user_balances"].get(key, 0),
        })
        if len(lst) > BALANCE_LOG_LIMIT:
            del lst[:len(lst) - BALANCE_LOG_LIMIT]
    except Exception as e:
        logging.info(f"Balans tarixini yozishda xato (e'tiborsiz): {e}")


def history_items(uid, limit: int = 50) -> list:
    """Eng yangisi birinchi bo'lgan tarix ro'yxati."""
    return list(reversed((data.get("balance_log") or {}).get(str(uid), [])))[:limit]


def history_text(uid) -> str:
    items = history_items(uid, 15)
    bal = data["user_balances"].get(str(uid), 0)
    if not items:
        return f"🧾 <b>To'lovlar tarixi</b>\n\n💰 Joriy balans: <b>{bal:,} so'm</b>\n\nHozircha harakatlar yo'q."
    lines = []
    for it in items:
        sign = "➕" if it["d"] >= 0 else "➖"
        when = it["t"][:16].replace("T", " ")
        lines.append(f"{sign} <b>{abs(it['d']):,} so'm</b> — {html_escape(it['r'])}\n<i>{when}</i>")
    return f"🧾 <b>To'lovlar tarixi</b> (oxirgi {len(items)} ta)\n💰 Joriy balans: <b>{bal:,} so'm</b>\n\n" + "\n\n".join(lines)


def promo_normalize(code: str) -> str:
    return re.sub(r"[^A-Z0-9_\-]", "", (code or "").strip().upper())[:32]


def promo_redeem(uid: int, code: str):
    """(ok, xabar, summa) qaytaradi. Muvaffaqiyatli bo'lsa balansni oshiradi va tarixga yozadi."""
    code = promo_normalize(code)
    promo = data["promo_codes"].get(code)
    if not code or not promo or not promo.get("active", True):
        return False, "❌ Bunday promo-kod topilmadi yoki faol emas.", 0
    if uid in promo.get("used_by", []):
        return False, "⚠️ Siz bu promo-koddan allaqachon foydalangansiz.", 0
    max_uses = int(promo.get("max_uses", 0) or 0)
    if max_uses and len(promo.get("used_by", [])) >= max_uses:
        return False, "😔 Bu promo-kodning foydalanish limiti tugagan.", 0
    amount = int(promo["amount"])
    key = str(uid)
    data["user_balances"][key] = data["user_balances"].get(key, 0) + amount
    promo.setdefault("used_by", []).append(uid)
    log_balance(uid, amount, f"Promo-kod {code}")
    save_data()
    return True, f"🎉 Promo-kod qabul qilindi! Hisobingizga <b>{amount:,} so'm</b> qo'shildi.\n💰 Joriy balans: <b>{data['user_balances'][key]:,} so'm</b>", amount


def _som(n) -> str:
    try:
        return f"{int(n):,}".replace(",", " ")
    except Exception:
        return str(n)


