def is_bot_owner(info: dict, uid) -> bool:
    try:
        return uid == info.get("admin_id") or bool(is_full_admin(uid))
    except Exception:
        return uid == info.get("admin_id")


def admin_has_perm(info: dict, uid, perm: str) -> bool:
    """Bot egasi — hamma narsa. Boshqa admin — faqat egasi bergan ruxsatlar. Yozuvi yo'q eski admin — to'liq."""
    if is_bot_owner(info, uid):
        return True
    if not is_admin(info, uid):
        return False
    perms = (info.get("admin_perms") or {}).get(str(uid))
    if perms is None:
        return True
    return perm in perms


def admin_perm_summary(info: dict, uid) -> str:
    if is_bot_owner(info, uid):
        return "👑 Bot egasi — to'liq"
    perms = (info.get("admin_perms") or {}).get(str(uid))
    if perms is None:
        return "✅ To'liq huquq"
    if not perms:
        return "🚫 Hech narsaga ruxsat yo'q"
    return f"🔐 {len(perms)}/{len(ADMIN_PERMS)} bo'lim"


def admins_kb():
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="➕ Admin qo'shish", callback_data="adm_add")],
        [InlineKeyboardButton(text="📋 Adminlar ro'yxati", callback_data="adm_list")],
        [InlineKeyboardButton(text="➖ Adminni o'chirish", callback_data="adm_del")],
    ])


def setup_admin_management(dp: Dispatcher, token: str):
    info = data["bots"][token]
    info.setdefault("admin_ids", [info.get("admin_id")])
    owner_id = info["admin_id"]

    @dp.message(Command("cancel"))
    async def cancel_cmd(message: Message, state: FSMContext):
        current = await state.get_state()
        if current is None:
            await message.answer("Bekor qilinadigan jarayon yo'q.")
            return
        await state.clear()
        await message.answer("❌ Jarayon bekor qilindi.")

    def _owner_ok(uid) -> bool:
        return is_bot_owner(info, uid)

    def _perm_text(target: int) -> str:
        perms = info.setdefault("admin_perms", {}).get(str(target))
        lines = [f"🔐 <b>Admin huquqlari</b>\n\n👤 ID: <code>{target}</code>",
                 "Yoqilgan bo'limlarni shu admin boshqara oladi. Qolganlari unga yopiq bo'ladi.\n"]
        full = perms is None
        for k, label in ADMIN_PERMS.items():
            on = full or k in perms
            lines.append(f"{'✅' if on else '⬜️'} {label}")
        return "\n".join(lines)

    def _perm_kb(target: int) -> InlineKeyboardMarkup:
        perms = info.setdefault("admin_perms", {}).get(str(target))
        full = perms is None
        rows = []
        for k, label in ADMIN_PERMS.items():
            on = full or k in perms
            rows.append([InlineKeyboardButton(text=f"{'✅' if on else '⬜️'} {label}"[:60], callback_data=f"admtg_{target}_{k}")])
        rows.append([
            InlineKeyboardButton(text="✅ Hammasi", callback_data=f"admall_{target}"),
            InlineKeyboardButton(text="🚫 Hech narsa", callback_data=f"admnone_{target}"),
        ])
        rows.append([InlineKeyboardButton(text="⬅️ Adminlar ro'yxati", callback_data="adm_list")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    async def _show_perms(callback: CallbackQuery, target: int):
        try:
            await callback.message.edit_text(_perm_text(target), reply_markup=_perm_kb(target))
        except TelegramBadRequest:
            pass

    @dp.message(Command("admins"))
    @dp.message(F.text == "👤 Adminlar")
    @dp.message(F.text == "👮 Adminlar")
    async def admins_panel(message: Message):
        if not is_admin(info, message.from_user.id):
            return
        if not _owner_ok(message.from_user.id):
            await message.answer("🚫 Adminlarni faqat bot egasi boshqara oladi.")
            return
        await message.answer("👤 Adminlar boshqaruvi:", reply_markup=admins_kb())

    @dp.callback_query(F.data == "adm_add")
    async def adm_add_cb(callback: CallbackQuery, state: FSMContext):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi admin qo'sha oladi.", show_alert=True)
            return
        await callback.message.answer("Yangi admin Telegram ID'ini yuboring (/myid orqali bilib olish mumkin):")
        await state.set_state(AddAdmin.waiting_id)
        await callback.answer()

    @dp.message(AddAdmin.waiting_id)
    async def adm_add_process(message: Message, state: FSMContext):
        if not _owner_ok(message.from_user.id):
            await state.clear()
            return
        try:
            new_id = int((message.text or "").strip())
        except ValueError:
            await message.answer("❌ Faqat raqam kiriting.")
            return
        if new_id <= 0:
            await message.answer("❌ ID noto'g'ri.")
            return
        await state.clear()
        is_new = new_id not in info["admin_ids"]
        if is_new:
            info["admin_ids"].append(new_id)
            # Yangi admin — boshida faqat minimal huquq; qolganini bot egasi o'zi belgilaydi
            info.setdefault("admin_perms", {})[str(new_id)] = list(ADMIN_PERM_DEFAULT)
            save_data()
        await message.answer(
            (f"✅ Admin qo'shildi: <code>{new_id}</code>\n\n" if is_new else f"ℹ️ <code>{new_id}</code> allaqachon admin.\n\n")
            + "Endi unga qaysi bo'limlarga ruxsat berishni tanlang 👇"
        )
        if new_id != owner_id:
            await message.answer(_perm_text(new_id), reply_markup=_perm_kb(new_id))

    @dp.callback_query(F.data == "adm_list")
    async def adm_list_cb(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            return
        lines = []
        rows = []
        for aid in info["admin_ids"]:
            tag = " (asosiy)" if aid == owner_id else ""
            lines.append(f"• <code>{aid}</code>{tag} — {admin_perm_summary(info, aid)}")
            if aid != owner_id and _owner_ok(callback.from_user.id):
                rows.append([InlineKeyboardButton(text=f"🔐 {aid} huquqlari", callback_data=f"admperm_{aid}")])
        kb = InlineKeyboardMarkup(inline_keyboard=rows) if rows else None
        text = "👤 <b>Adminlar:</b>\n\n" + "\n".join(lines)
        if callback.message and callback.data == "adm_list" and rows:
            # huquqlar oynasidan "Orqaga" bosilganda o'sha xabar tahrirlanadi
            try:
                await callback.message.edit_text(text, reply_markup=kb)
                await callback.answer()
                return
            except TelegramBadRequest:
                pass
        await callback.message.answer(text, reply_markup=kb)
        await callback.answer()

    @dp.callback_query(F.data.startswith("admperm_"))
    async def adm_perm_open(callback: CallbackQuery):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi.", show_alert=True)
            return
        target = int(callback.data.split("_", 1)[1])
        if target not in info["admin_ids"] or target == owner_id:
            await callback.answer("Admin topilmadi.", show_alert=True)
            return
        await _show_perms(callback, target)
        await callback.answer()

    @dp.callback_query(F.data.startswith("admtg_"))
    async def adm_perm_toggle(callback: CallbackQuery):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi.", show_alert=True)
            return
        _, tid, key = callback.data.split("_", 2)
        target = int(tid)
        if target not in info["admin_ids"] or target == owner_id or key not in ADMIN_PERMS:
            await callback.answer()
            return
        store = info.setdefault("admin_perms", {})
        cur = store.get(str(target))
        if cur is None:                      # eski "to'liq" admin — avval hammasini aniq ro'yxatga aylantiramiz
            cur = list(ADMIN_PERMS.keys())
        cur = list(cur)
        if key in cur:
            cur.remove(key)
        else:
            cur.append(key)
        store[str(target)] = cur
        save_data()
        await _show_perms(callback, target)
        await callback.answer()

    @dp.callback_query(F.data.startswith("admall_") | F.data.startswith("admnone_"))
    async def adm_perm_bulk(callback: CallbackQuery):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi.", show_alert=True)
            return
        kind, tid = callback.data.split("_", 1)
        target = int(tid)
        if target not in info["admin_ids"] or target == owner_id:
            await callback.answer()
            return
        info.setdefault("admin_perms", {})[str(target)] = list(ADMIN_PERMS.keys()) if kind == "admall" else []
        save_data()
        await _show_perms(callback, target)
        await callback.answer("✅ Yangilandi")

    @dp.callback_query(F.data == "adm_del")
    async def adm_del_cb(callback: CallbackQuery):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi adminni o'chira oladi.", show_alert=True)
            return
        removable = [aid for aid in info["admin_ids"] if aid != owner_id]
        if not removable:
            await callback.message.answer("O'chirish uchun qo'shimcha admin yo'q.")
            await callback.answer()
            return
        buttons = [[InlineKeyboardButton(text=str(aid), callback_data=f"admdel_{aid}")] for aid in removable]
        await callback.message.answer("O'chirmoqchi bo'lgan adminni tanlang:", reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons))
        await callback.answer()

    @dp.callback_query(F.data.startswith("admdel_"))
    async def adm_delid_cb(callback: CallbackQuery):
        if not _owner_ok(callback.from_user.id):
            await callback.answer("🚫 Faqat bot egasi.", show_alert=True)
            return
        target_id = int(callback.data.split("_", 1)[1])
        if target_id in info["admin_ids"] and target_id != owner_id:
            info["admin_ids"].remove(target_id)
            info.get("admin_perms", {}).pop(str(target_id), None)
            save_data()
            await callback.message.answer(f"🗑 Admin o'chirildi: {target_id}")
        await callback.answer()


