async def tg_api(token: str, method: str, params: dict = None, file: tuple = None, timeout: int = 30):
    """Telegram Bot API'ga to'g'ridan-to'g'ri so'rov (aiogram versiyasidan mustaqil).
    Muvaffaqiyatda 'result' qaytaradi, xatoda RuntimeError (Telegram izohi bilan)."""
    import aiohttp
    form = aiohttp.FormData()
    for k, v in (params or {}).items():
        form.add_field(k, v if isinstance(v, str) else json.dumps(v, ensure_ascii=False))
    if file:
        fname, content = file
        form.add_field("pic", content, filename=fname, content_type="application/octet-stream")
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=timeout)) as sess:
        async with sess.post(f"https://api.telegram.org/bot{token}/{method}", data=form) as r:
            js = await r.json(content_type=None)
    if not js.get("ok"):
        raise RuntimeError(js.get("description", "Telegram xatosi"))
    return js.get("result")


