    # Admin: /promo KOD SUMMA [LIMIT]  va  /promos
    @dp.message(Command("promo"))
    async def promo_create_cmd(message: Message):
        if not is_full_admin(message.from_user.id):
            return
        parts = (message.text or "").split()
        try:
            code = promo_normalize(parts[1])
            amount = int(parts[2])
            max_uses = int(parts[3]) if len(parts) > 3 else 0
            if not code or amount <= 0 or max_uses < 0:
                raise ValueError
        except (IndexError, ValueError):
            await message.answer(
                "Foydalanish: <code>/promo KOD SUMMA [LIMIT]</code>\n"
                "Masalan: <code>/promo YANGI50 5000 100</code> (LIMIT bo'lmasa — cheksiz)\n"
                "Ro'yxat: /promos"
            )
            return
        data["promo_codes"][code] = {
            "amount": amount, "max_uses": max_uses, "used_by": [],
            "active": True, "created_at": datetime.now().isoformat(timespec="seconds"),
        }
        save_data()
        await message.answer(f"✅ Promo-kod yaratildi: <code>{code}</code> — {amount:,} so'm, limit: {max_uses or 'cheksiz'}")

