    @dp.message(TopUpFlow.waiting_amount)
    async def topup_amount_process(message: Message, state: FSMContext):
        try:
            amount = int(message.text.strip().replace(" ", ""))
        except ValueError:
            await message.answer("❌ Faqat raqam kiriting.")
