    # ---------- ⚙️ Bot sozlamalari, 👤 Profil, 🗑 O'chirish, 💰 To'lov va obuna ----------
    def mb_access(uid: int, bot_id: int, owner_only: bool = False):
        token, info = find_bot_by_id(bot_id)
        if not info:
            return None, None
        if owner_only:
            ok = uid == info.get("admin_id")
        else:
            ok = uid in info.get("admin_ids", [info.get("admin_id")])
        return (token, info) if ok else (None, None)

    async def mb_username(token: str, info: dict):
        if info.get("username"):
            return info["username"]
        try:
            me = await tg_api(token, "getMe")
            info["username"] = me.get("username")
            save_data()
        except Exception:
            return None
        return info.get("username")

