    async def mb_profile_view(token: str, info: dict):
        async def _get(method, key):
            try:
                r = await tg_api(token, method)
                return (r or {}).get(key) or "—"
            except Exception:
                return "—"
        name = await _get("getMyName", "name")
        bio = await _get("getMyShortDescription", "short_description")
        desc = await _get("getMyDescription", "description")
