    @dp.message(BotMgrFlow.waiting_photo)
    async def mgr_photo_received(message: Message, state: FSMContext):
        if not message.photo:
            if await mgr_guard(message, state):
                return
            await message.answer("🖼 Iltimos, rasmni oddiy rasm (surat) ko'rinishida yuboring.")
            return
        token, info = await mgr_ctx(message, state)
        if not info:
            return
        try:
            buf = await message.bot.download(message.photo[-1].file_id)
            content = buf.read() if hasattr(buf, "read") else bytes(buf)
            await tg_api(token, "setMyProfilePhoto",
                         {"photo": {"type": "static", "photo": "attach://pic"}}, file=("photo.jpg", content), timeout=60)
        except Exception as e:
            await message.answer(f"❌ Rasm o'rnatilmadi: {html_escape(str(e)[:200])}", reply_markup=mb_back_kb(info["id"], "prof"))
            return
        await mgr_profile_done(message, state, token, info, "✅ Profil rasmi o'rnatildi.")

    @dp.message(BotMgrFlow.waiting_cmds)
    async def mgr_cmds_received(message: Message, state: FSMContext):
        token, info = await mgr_ctx(message, state)
        if not info:
            return
        raw = (message.text or "").strip()
        if raw == "0":
            try:
                await tg_api(token, "deleteMyCommands")
            except Exception as e:
                await message.answer(f"❌ {html_escape(str(e)[:200])}", reply_markup=mb_back_kb(info["id"], "prof"))
                return
            await mgr_profile_done(message, state, token, info, "🗑 Buyruqlar o'chirildi.")
            return
        cmds, bad = [], []
        for line in raw.splitlines():
            line = line.strip()
            if not line:
                continue
            m = re.match(r"^/?([A-Za-z0-9_]{1,32})\s*[-—:]\s*(.{1,256})$", line)
            if m:
                cmds.append({"command": m.group(1).lower(), "description": m.group(2).strip()[:256]})
            else:
                bad.append(line[:40])
        if bad or not cmds:
            await message.answer("❌ Format noto'g'ri. Har qatorga bittadan yuboring:\n<code>start - Botni ishga tushirish</code>"
                                 + (f"\n\nXato qator: <code>{html_escape(bad[0])}</code>" if bad else ""),
                                 reply_markup=mb_back_kb(info["id"], "prof"))
            return
        try:
            await tg_api(token, "setMyCommands", {"commands": cmds[:100]})
        except Exception as e:
            await message.answer(f"❌ {html_escape(str(e)[:200])}", reply_markup=mb_back_kb(info["id"], "prof"))
            return
        await mgr_profile_done(message, state, token, info, f"✅ Buyruqlar saqlandi ({len(cmds)} ta).")

