    @dp.callback_query(F.data.startswith("klang_"))
    async def kino_lang_set(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        code = callback.data.split("_", 1)[1]
        if code not in KINO_LANGS:
            await callback.answer()
            return
        info["language"] = code
        save_data()
        try:
            await callback.message.edit_reply_markup(reply_markup=lang_kb())
        except TelegramBadRequest:
            pass
        await callback.answer(f"✅ Bot tili: {KINO_LANGS[code]}")

