    # ---------- 🎨 Dizayn ----------
    KCLR_NAME = {"primary": "🔵 Ko'k", "success": "🟢 Yashil", "danger": "🔴 Qizil"}
    KCLR_EMOJI = {"primary": "🔵", "success": "🟢", "danger": "🔴"}
    KCLR_CODES = {"p": "primary", "s": "success", "d": "danger"}
    KCLR_PER_PAGE = 8

    def kclr_seed():
        """Bot menyularidagi tugmalarni (hali yuborilmagan bo'lsa ham) ro'yxatga oladi."""
        seen = info.setdefault("btn_seen", [])
        for fn in (customer_menu_kb, ultra_admin_kb, content_menu_kb, content_extra_kb, categories_menu_kb,
                   featured_menu_kb, top_menu_kb, users_menu_kb, ads_menu_kb, broadcast_menu_kb,
                   moderators_menu_kb, settings_menu_kb):
            try:
                for row in fn().keyboard:
                    for b in row:
                        if getattr(b, "text", None):
                            _btn_seen_add(_btn_key(b.text), seen)
            except Exception as e:
                logging.info(f"Dizayn: tugmalarni ro'yxatga olishda xato (e'tiborsiz): {e}")
        del seen[300:]

    def kclr_find(h: str):
        for t in list(info.get("btn_colors", {})) + list(info.get("btn_seen", [])):
            if btn_hash(t) == h:
                return t
        return None

    def kclr_panel_text() -> str:
        gd = info.get("btn_default_color")
        return (
            "🎨 <b>Dizayn — tugma ranglari</b>\n\n"
            f"Hamma tugmalar rangi: <b>{KCLR_NAME.get(gd, '⚪ Standart')}</b>\n"
            f"Alohida rang berilgan tugmalar: <b>{len(info.get('btn_colors', {}))}</b>\n\n"
            "Rang mijozlar va adminlar ko'radigan barcha tugmalarga qo'llanadi. "
            "Avval «Hamma tugmalar» uchun bir rang tanlang, so'ng kerakli tugmalarni alohida bo'yang "
            "(alohida rang umumiy rangdan ustun turadi).\n"
            "Telegram faqat 3 xil rang beradi: ko'k, yashil, qizil."
        )

    def kclr_panel_kb():
        rows = [
            [InlineKeyboardButton(text="🔵 Hammasi ko'k", callback_data="kclr_all_p"),
             InlineKeyboardButton(text="🟢 Hammasi yashil", callback_data="kclr_all_s")],
            [InlineKeyboardButton(text="🔴 Hammasi qizil", callback_data="kclr_all_d"),
             InlineKeyboardButton(text="⚪ Standart", callback_data="kclr_all_n")],
            [InlineKeyboardButton(text="📋 Tugmalar ro'yxati", callback_data="kclr_pg_0")],
            [InlineKeyboardButton(text="🎨 Rang berilganlar", callback_data="kclr_cfg_0")],
            [InlineKeyboardButton(text="♻️ Alohida ranglarni tozalash", callback_data="kclr_reset")],
        ]
        panel_url = get_kinopanel_url(info.get("id"))
        if panel_url:
            rows.append([InlineKeyboardButton(text="🌐 Web panel (ko'rinish)", web_app=WebAppInfo(url=panel_url))])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    def kclr_list_kb(texts: list, page: int, prefix: str):
        pages = max(1, (len(texts) + KCLR_PER_PAGE - 1) // KCLR_PER_PAGE)
        page = max(0, min(page, pages - 1))
        colors = info.get("btn_colors", {})
        rows = [
            [InlineKeyboardButton(text=f"{KCLR_EMOJI.get(colors.get(t), '⚪')} {t[:40]}", callback_data=f"kclr_pick_{btn_hash(t)}")]
            for t in texts[page * KCLR_PER_PAGE:(page + 1) * KCLR_PER_PAGE]
        ]
        nav = []
        if page > 0:
            nav.append(InlineKeyboardButton(text="◀️", callback_data=f"{prefix}{page - 1}"))
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="kclr_noop"))
        if page < pages - 1:
            nav.append(InlineKeyboardButton(text="▶️", callback_data=f"{prefix}{page + 1}"))
        rows.append(nav)
        rows.append([InlineKeyboardButton(text="◀️ Orqaga", callback_data="kclr_root")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    def kclr_pick_text(t: str) -> str:
        cur = info.get("btn_colors", {}).get(_btn_key(t))
        return f"🎨 Tugma: <b>{html_escape(t)}</b>\n\nHozirgi rang: {KCLR_NAME.get(cur, '⚪ Standart (umumiy rang)')}\n\nYangi rangni tanlang:"

    def kclr_pick_kb(t: str):
        h = btn_hash(t)
        return InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🔵 Ko'k", callback_data=f"kclr_set_{h}_p"),
             InlineKeyboardButton(text="🟢 Yashil", callback_data=f"kclr_set_{h}_s")],
            [InlineKeyboardButton(text="🔴 Qizil", callback_data=f"kclr_set_{h}_d"),
             InlineKeyboardButton(text="⚪ Standart", callback_data=f"kclr_set_{h}_n")],
            [InlineKeyboardButton(text="◀️ Orqaga", callback_data="kclr_root")],
        ])

    async def kclr_edit(callback: CallbackQuery, text: str, kb):
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except TelegramBadRequest as e:
            if "not modified" not in str(e).lower():
                logging.info(f"Dizayn paneli tahrirlanmadi: {e}")

