    @dp.callback_query(F.data.startswith("kclr_pick_"))
    async def kclr_pick_cb(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            return
        t = kclr_find(callback.data.split("_", 2)[2])
        if not t:
            await callback.answer("Tugma topilmadi.", show_alert=True)
            return
        await kclr_edit(callback, kclr_pick_text(t), kclr_pick_kb(t))
        await callback.answer()

    @dp.callback_query(F.data.startswith("kclr_set_"))
    async def kclr_set_cb(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            return
        parts = callback.data.split("_")
        if len(parts) != 4:
            await callback.answer()
            return
        t = kclr_find(parts[2])
        if not t:
            await callback.answer("Tugma topilmadi.", show_alert=True)
            return
        colors = info.setdefault("btn_colors", {})
        key = _btn_key(t)
        if parts[3] == "n":
            colors.pop(key, None)
        elif parts[3] in KCLR_CODES:
            colors[key] = KCLR_CODES[parts[3]]
        else:
            await callback.answer()
            return
        save_data()
        await kclr_edit(callback, kclr_pick_text(t), kclr_pick_kb(t))
        await callback.answer("Saqlandi!")

