    # ---------- 🔘 Film tagidagi tugmalar (Boshqa kodlar, Ulashish, Instagram va h.k.) ----------
    FB_MAX = 8
    FB_PRESETS = {
        "codes": "🎬 Boshqa kodlar",
        "ads": "📣 Reklama uchun",
        "insta": "📸 Instagram",
        "tg": "📢 Telegram kanal",
    }

    def fb_list() -> list:
        lst = info.setdefault("film_buttons", [])
        return lst

    def fb_norm_url(raw: str):
        """Foydalanuvchi yozgan havolani tekshiradi: @username, t.me/..., instagram.com/... va to'liq URL qabul qilinadi."""
        s = (raw or "").strip()
        if not s or " " in s or len(s) > 400:
            return None
        if s.startswith("@") and re.fullmatch(r"@[A-Za-z0-9_]{4,32}", s):
            return "https://t.me/" + s[1:]
        low = s.lower()
        if low.startswith("tg://"):
            return s
        if not (low.startswith("http://") or low.startswith("https://")):
            s = "https://" + s
        host = re.sub(r"^https?://", "", s, flags=re.I).split("/")[0]
        if "." not in host or len(host) < 4:
            return None
        return s

    def film_buttons_rows(share_link: str = "") -> list:
        """Filmning tagiga qo'yiladigan URL-tugmalar (inline qatorlar)."""
        if not info.get("film_buttons_on", True):
            return []
        btns = []
        for b in fb_list():
            if b.get("kind") == "share":
                if not share_link:
                    continue
                share_text = info.get("film_share_text") or "🎬 Kinolarni shu botda ko'ring!"
                url = "https://t.me/share/url?url=" + quote(share_link) + "&text=" + quote(share_text)
            else:
                url = b.get("url")
            if url and b.get("text"):
                btns.append(InlineKeyboardButton(text=b["text"][:40], url=url))
        cols = 1 if info.get("film_buttons_cols") == 1 else 2
        return [btns[i:i + cols] for i in range(0, len(btns), cols)]

    def fb_share_link() -> str:
        u = _bot_username.get("u")
        return f"https://t.me/{u}" if u else ""

    def fb_panel_text() -> str:
        on = info.get("film_buttons_on", True)
        cols = 1 if info.get("film_buttons_cols") == 1 else 2
        state_txt = "🟢 Yoqilgan" if on else "🔴 O'chirilgan"
        lines = [
            "🔘 <b>Film tagidagi tugmalar</b>", "",
            "Foydalanuvchiga film yuborilganda, filmning tagida shu tugmalar chiqadi: "
            "«Boshqa kodlar», «Ulashish», «Instagram», «Reklama uchun» va h.k.", "",
            f"Holati: <b>{state_txt}</b>   •   Qatorda: <b>{cols}</b> ta   •   Tugmalar: <b>{len(fb_list())}/{FB_MAX}</b>",
        ]
        if not fb_list():
            lines += ["", "<i>Hozircha tugma yo'q. «➕ Tugma qo'shish» ni bosing.</i>"]
        return "\n".join(lines)

    def fb_panel_kb() -> InlineKeyboardMarkup:
        rows = [[InlineKeyboardButton(text="➕ Tugma qo'shish", callback_data="fb_add")]]
        for b in fb_list():
            bid = b["id"]
            icon = "↗️" if b.get("kind") == "share" else "🔗"
