    @dp.callback_query(F.data.startswith("obf_"))
    async def fav_toggle(callback: CallbackQuery):
        p = PR().get(callback.data.split("_", 1)[1])
        if not p:
            await callback.answer("Loyiha topilmadi", show_alert=True)
            return
        uid = callback.from_user.id
        if uid in p["favs"]:
            p["favs"].remove(uid)
            await callback.answer("Sevimlilardan olindi")
