        text = f"🏛 {p['title']}\n💰 {money(p.get('budget'))}\n\nLoyiha bilan tanishing va rasmiy saytda o'zingiz ovoz bering:\n{link}"
        url = f"https://t.me/share/url?url={quote(link)}&text={quote(text)}"
        await callback.message.answer("📤 Do'stlarga ulashing:", reply_markup=InlineKeyboardMarkup(
            inline_keyboard=[[InlineKeyboardButton(text="📤 Telegramda ulashish", url=url)]]))
