    @dp.message(F.text == "🔎 Qidirish")
    async def search_start(message: Message, state: FSMContext):
        await message.answer("🔎 Loyiha nomi, hudud yoki raqamini yozing:")
        await state.set_state(OBSearch.q)

    @dp.message(OBSearch.q)
    async def search_do(message: Message, state: FSMContext):
        q = (message.text or "").strip().lower()
        await state.clear()
        if not q:
            await message.answer("Matn yozing.")
            return
        ids = [p["id"] for p in PR().values()
               if q == p["id"] or q in p["title"].lower() or q in (p.get("region") or "").lower() or q in (p.get("category") or "").lower()]
        if not ids:
            await message.answer("😕 Hech narsa topilmadi.")
            return
        lastq[message.from_user.id] = ids
        await show_list(message, "q", 0, 0, ids=ids, title="🔎 <b>Qidiruv natijalari</b>")

