    # ---------- Viktorina ----------
    def quiz_msg(qi, score):
        q, opts, _ = OB_QUIZ[qi]
        kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text=o, callback_data=f"obq_{qi}_{i}_{score}")] for i, o in enumerate(opts)])
        return f"🧠 <b>Savol {qi + 1}/{len(OB_QUIZ)}</b>\n\n{q}", kb

    @dp.message(F.text == "🧠 Viktorina")
    async def quiz_start(message: Message):
        t, kb = quiz_msg(0, 0)
        await message.answer(t, reply_markup=kb)

    @dp.callback_query(F.data.startswith("obq_"))
    async def quiz_answer(callback: CallbackQuery):
        _, qi, ch, score = callback.data.split("_")
        qi, ch, score = int(qi), int(ch), int(score)
        ok = ch == OB_QUIZ[qi][2]
        score += 1 if ok else 0
        await callback.answer("✅ To'g'ri!" if ok else "❌ Noto'g'ri. To'g'ri javob: " + OB_QUIZ[qi][1][OB_QUIZ[qi][2]], show_alert=not ok)
        if qi + 1 < len(OB_QUIZ):
            t, kb = quiz_msg(qi + 1, score)
            await callback.message.edit_text(t, reply_markup=kb)
        else:
            uid = str(callback.from_user.id)
            info["ob_quiz_best"][uid] = max(score, info["ob_quiz_best"].get(uid, 0))
            save_data()
            await callback.message.edit_text(f"🏁 Natija: <b>{score}/{len(OB_QUIZ)}</b>\nEng yaxshi natijangiz: {info['ob_quiz_best'][uid]}/{len(OB_QUIZ)}")

