    @dp.message(OBEdit.value)
    async def edit_save(message: Message, state: FSMContext):
        if await cancelled(message, state):
            return
        d = await state.get_data()
        p = PR().get(d.get("pid"))
        field = d.get("field")
        if not p:
            await state.clear()
            return
        if field == "photo":
            if not message.photo:
                await message.answer("Rasm yuboring.")
                return
            p["photo"] = message.photo[-1].file_id
        else:
            t = (message.text or "").strip()
            if field == "budget":
                t = t.replace(" ", "")
                if not t.isdigit():
                    await message.answer("❌ Faqat raqam.")
                    return
                p["budget"] = int(t)
            elif field == "link":
                if t != "-" and not t.startswith("http"):
                    await message.answer("❌ Havola http bilan boshlansin yoki «-».")
                    return
                p["link"] = "" if t == "-" else t
            elif field in ("title", "desc", "region", "category"):
                if not t:
                    await message.answer("Matn yuboring.")
                    return
                p[field] = t[:700 if field == "desc" else 150]
        save_data()
        await state.clear()
        await message.answer("✅ Saqlandi.", reply_markup=admin_kb())
        await send_card(message, p, message.from_user.id)

