    @dp.message(F.text == "📅 Muddat belgilash")
    async def dl_start(message: Message, state: FSMContext):
        if not adm(message):
            return
        await message.answer(deadline_text() + "\n\nYangi muddatni yozing: <code>25.12.2026 23:59</code>\nO'chirish uchun «-» yozing.", reply_markup=cancel_kb)
        await state.set_state(OBDeadline.val)

    @dp.message(OBDeadline.val)
    async def dl_save(message: Message, state: FSMContext):
        if await cancelled(message, state):
            return
        t = (message.text or "").strip()
        if t == "-":
            info["ob_deadline"] = ""
        else:
            dt = None
            for f in ("%d.%m.%Y %H:%M", "%d.%m.%Y", "%Y-%m-%d %H:%M", "%Y-%m-%d"):
                try:
                    dt = datetime.strptime(t, f)
                    if f in ("%d.%m.%Y", "%Y-%m-%d"):
                        dt = dt.replace(hour=23, minute=59)
                    break
                except ValueError:
                    continue
            if not dt:
                await message.answer("❌ Format noto'g'ri. Masalan: 25.12.2026 23:59")
                return
            info["ob_deadline"] = dt.isoformat()
        save_data()
        await state.clear()
        await message.answer("✅ Saqlandi.\n" + deadline_text(), reply_markup=admin_kb())

