    # ---------- Admin: xabar yuborish, eslatma ----------
    async def broadcast(bot, ids, send):
        ok = bad = 0
        for u in ids:
            try:
                await send(u)
                ok += 1
            except TelegramForbiddenError:
                bad += 1
            except Exception:
                bad += 1
            await asyncio.sleep(0.05)
        return ok, bad

    @dp.message(F.text == "📣 Xabar yuborish")
    async def cast_start(message: Message, state: FSMContext):
        if not adm(message):
            return
        await message.answer(f"📣 Barcha foydalanuvchilarga ({len(info['users'])} ta) yuboriladigan xabarni yuboring (matn, rasm, video...):", reply_markup=cancel_kb)
        await state.set_state(OBCast.msg)

    @dp.message(OBCast.msg)
    async def cast_do(message: Message, state: FSMContext):
        if await cancelled(message, state):
            return
        await state.clear()
        await message.answer("⏳ Yuborilmoqda...", reply_markup=admin_kb())
        ids = [u for u in info["users"] if u not in info["blocked_users"] and u != message.from_user.id]
        ok, bad = await broadcast(message.bot, ids, lambda u: message.bot.copy_message(u, message.chat.id, message.message_id))
        await message.answer(f"✅ Yuborildi: {ok}\n❌ Yetmadi: {bad}")

