    @dp.message(F.text == "📊 Statistika")
    async def stats_msg(message: Message):
        if not adm(message):
            return
        td = today_s()
        new_today = sum(1 for d in info["ob_join"].values() if d == td)
        votes = sum(len(p["voted"]) for p in PR().values())
        favs = sum(len(p["favs"]) for p in PR().values())
        views = sum(p.get("views", 0) for p in PR().values())
        refs = sum(len(v) for v in info["ob_referrals"].values())
        pend = sum(1 for v in info["ob_feedback"].values() if not v.get("answered"))
        top = sorted(PR().values(), key=lambda p: -len(p["voted"]))[:3]
        tl = "\n".join(f"  {n}. {esc(p['title'])} — {len(p['voted'])}" for n, p in enumerate(top, 1)) or "  —"
        await message.answer(
            f"📊 <b>Statistika</b>\n\n👥 Foydalanuvchilar: {len(info['users'])} (bugun +{new_today})\n🚫 Bloklangan: {len(info['blocked_users'])}\n"
            f"📋 Loyihalar: {len(PR())}\n👁 Ko'rishlar: {views}\n✅ Belgilangan ovozlar: {votes}\n⭐ Sevimlilar: {favs}\n"
            f"👥 Takliflar: {refs}\n🔔 Eslatma obunachilari: {len(info['ob_remind'])}\n📞 Javobsiz murojaatlar: {pend}\n\n🏆 Top:\n{tl}")

    @dp.message(F.text == "🚫 Bloklash")
    async def block_start(message: Message, state: FSMContext):
        if not adm(message):
            return
        await message.answer("Foydalanuvchi ID sini yuboring (bloklash/blokdan chiqarish):", reply_markup=cancel_kb)
        await state.set_state(OBBlock.uid)

    @dp.message(OBBlock.uid)
    async def block_do(message: Message, state: FSMContext):
        if await cancelled(message, state):
            return
        t = (message.text or "").strip()
        if not t.isdigit():
            await message.answer("❌ Faqat ID raqam.")
            return
        u = int(t)
        if is_admin(info, u):
            await message.answer("Adminni bloklab bo'lmaydi.")
            return
        if u in info["blocked_users"]:
            info["blocked_users"].remove(u)
            r = "✅ Blokdan chiqarildi."
        else:
            info["blocked_users"].append(u)
            r = "🚫 Bloklandi."
        save_data()
        await state.clear()
        await message.answer(r, reply_markup=admin_kb())

    @dp.message(F.text == "📤 Eksport")
    async def export_csv(message: Message):
        if not adm(message):
            return
        buf = ["id,name,joined,referrals,voted,favorites,blocked"]
        for u in info["users"]:
            nm = str(info["ob_names"].get(str(u), "")).replace(",", " ").replace("\n", " ")
            voted = sum(1 for p in PR().values() if u in p["voted"])
            favs = sum(1 for p in PR().values() if u in p["favs"])
            buf.append(f"{u},{nm},{info['ob_join'].get(str(u), '')},{len(info['ob_referrals'].get(str(u), []))},{voted},{favs},{int(u in info['blocked_users'])}")
        await message.answer_document(BufferedInputFile("\n".join(buf).encode("utf-8-sig"), filename="openbudget_users.csv"), caption=f"📤 {len(info['users'])} ta foydalanuvchi")

