    @dp.message(NkOrder.waiting_search, F.text)
    async def nk_search_in(message: Message, state: FSMContext):
        words = message.text.lower().split()
        res = []
        for sid, s in enabled_services().items():
            hay = f"{s['name']} {s.get('category', '')}".lower()
            if all(w in hay for w in words):
                res.append((sid, s))
        await state.clear()
        if not res:
            await message.answer("😔 Hech narsa topilmadi. Boshqa so'z bilan urinib ko'ring.")
            return
        res.sort(key=lambda x: price_1000(x[1]))
        rows = [[InlineKeyboardButton(text=f"{s['name'][:34]} — {som(price_1000(s))}", callback_data=f"nksv_{sid}")]
                for sid, s in res[:15]]
        await message.answer(f"🔍 Topildi: {len(res)} ta (eng arzon 15 tasi)", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    # ---------------------------------------------------------------- buyurtmalar
    def my_orders(uid: int, limit: int = 10):
        mine = [(oid, o) for oid, o in info["nk_orders"].items() if o["uid"] == uid]
        mine.sort(key=lambda x: x[1]["created_at"], reverse=True)
        return mine[:limit]

