    async def nk_my_orders(message: Message, state: FSMContext):
        await state.clear()
        if not await guard(message):
            return
        mine = my_orders(message.from_user.id)
        if not mine:
            await message.answer("📦 Sizda hali buyurtmalar yo'q. «🛍 Xizmatlar» orqali birinchi buyurtmangizni bering!")
            return
        lines = [f"{NK_STATUS_EMOJI.get(o['status'], '❔')} <b>#{oid}</b> — {esc(o['name'][:30])}\n"
                 f"   🔢 {o['qty']:,} · 💰 {som(o['price'])} so'm · {NK_STATUS_LABEL.get(o['status'], '')}" for oid, o in mine]
        btns = [InlineKeyboardButton(text=f"🔄 #{oid}", callback_data=f"nkst_{oid}") for oid, _ in mine]
        rows = [btns[i:i + 3] for i in range(0, len(btns), 3)]
