    @dp.message(F.text == "🎁 Kunlik bonus")
    async def nk_daily_bonus(message: Message, state: FSMContext):
        await state.clear()
        if not await guard(message):
            return
        amount = int(S.get("daily_bonus", 0))
        if amount <= 0:
            await message.answer("🎁 Kunlik bonus hozircha o'chirilgan.")
            return
        uid = message.from_user.id
        last = info["nk_bonus"].get(str(uid))
        if last:
            try:
                passed = datetime.now() - datetime.fromisoformat(last)
                if passed < timedelta(hours=24):
                    left = timedelta(hours=24) - passed
                    h, m = left.seconds // 3600, (left.seconds % 3600) // 60
                    await message.answer(f"⏳ Bonusni qayta olish uchun <b>{h} soat {m} daqiqa</b> kuting.")
                    return
            except Exception:
                pass
        info["nk_bonus"][str(uid)] = datetime.now().isoformat(timespec="seconds")
        add_bal(uid, amount, "Kunlik bonus")
        save_data()
        await message.answer(f"🎉 Kunlik bonus: <b>+{som(amount)} so'm</b>!\n💰 Balans: {som(bal(uid))} so'm")

