    @dp.message(NkPromoUse.waiting_code, F.text)
    async def nk_promo_in(message: Message, state: FSMContext):
        code = promo_normalize(message.text)
        uid = message.from_user.id
        p = info["nk_promos"].get(code)
        await state.clear()
        if not code or not p or not p.get("active", True):
            await message.answer("❌ Bunday promo-kod topilmadi yoki faol emas.")
            return
        if uid in p.get("used_by", []):
            await message.answer("⚠️ Siz bu promo-koddan allaqachon foydalangansiz.")
            return
        if int(p.get("max_uses", 0)) and len(p.get("used_by", [])) >= int(p["max_uses"]):
            await message.answer("😔 Bu promo-kodning limiti tugagan.")
            return
        p.setdefault("used_by", []).append(uid)
        add_bal(uid, int(p["amount"]), f"Promo-kod {code}")
        save_data()
        await message.answer(f"🎉 Promo-kod qabul qilindi! <b>+{som(p['amount'])} so'm</b>\n💰 Balans: {som(bal(uid))} so'm")

