    # ================================================================ ADMIN
    @dp.message(Command("stats"))
    @dp.message(F.text == "📊 Statistika")
    async def nk_admin_stats(message: Message):
        if not is_admin(info, message.from_user.id):
            return
        orders = info["nk_orders"]
        today = datetime.now().strftime("%Y-%m-%d")
        pending = sum(1 for o in orders.values() if o["status"] in NK_ACTIVE)
        done = [o for o in orders.values() if o["status"] == "bajarildi"]
        profit = sum(o["price"] - o["cost"] for o in done if o.get("cost"))
        svcs = info["nk_services"]
        await message.answer(
            "📊 <b>Statistika</b>\n\n"
            f"👥 Foydalanuvchilar: {len(info['users'])}\n"
            f"📦 Buyurtmalar: {len(orders)} (bugun: {sum(1 for o in orders.values() if o['created_at'].startswith(today))})\n"
            f"⏳ Jarayondagilar: {pending}\n✅ Bajarilgan: {len(done)}\n"
            f"💰 Savdo aylanmasi: {som(st['revenue'])} so'm\n📈 Taxminiy foyda (API xizmatlar): {som(profit)} so'm\n"
            f"➕ Jami to'ldirilgan: {som(st['topups'])} so'm\n💳 Foydalanuvchilar balansi: {som(sum(info['nk_balances'].values()))} so'm\n"
            f"🛍 Xizmatlar: {len(svcs)} (yoqilgan: {len(enabled_services())})\n"
            f"🔌 Rejim: {'API' if api_ready() else 'Qoʻlda'} · 🛠 Texnik rejim: {'yoqilgan' if S.get('maintenance') else 'oʻchiq'}")

    # ---- API sozlamalari
    def api_panel_text() -> str:
        key = info.get("nk_api_key") or ""
        masked = (key[:4] + "…" + key[-3:]) if len(key) > 8 else ("•••" if key else "—")
        return (f"🔑 <b>API sozlamalari</b>\n\n🔗 URL: <code>{esc(info.get('nk_api_url') or '—')}</code>\n🗝 Kalit: <code>{esc(masked)}</code>\n"
                f"🔌 Rejim: <b>{'API (avtomatik)' if api_ready() else 'Qoʻlda'}</b>\n\n"
                "JustAnotherPanel (v2) formatidagi har qanday SMM-panel ulanadi. API'ni o'chirsangiz, bot qo'lda rejimda ishlaydi.")

    def api_kb():
        return InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🔗 URL o'zgartirish", callback_data="nkapi_url"),
             InlineKeyboardButton(text="🗝 Kalit o'zgartirish", callback_data="nkapi_key")],
            [InlineKeyboardButton(text="🧪 Ulanishni tekshirish", callback_data="nkapi_test")],
            [InlineKeyboardButton(text="🗑 API'ni o'chirish", callback_data="nkapi_clear")],
        ])

    @dp.message(F.text == "🔑 API sozlamalari")
    async def nk_api_panel(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        await state.clear()
        await message.answer(api_panel_text(), reply_markup=api_kb())

