    # ---- xizmatlarni boshqarish
    @dp.message(F.text == "🛠 Xizmatlarni boshqarish")
    async def nk_manage_services(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        await state.clear()
        if not info["nk_services"]:
            await message.answer("Xizmatlar yo'q. «🔄 Xizmatlarni yangilash» yoki «➕ Xizmat qo'shish» dan foydalaning.")
            return
        counts: dict = {}
        for s in info["nk_services"].values():
            k = nk_platform_of(s)
            counts[k] = counts.get(k, 0) + 1
        btns = [InlineKeyboardButton(text=f"{label} ({counts[key]})", callback_data=f"nkam_{key}_0")
                for key, label, _ in NK_PLATFORMS if key in counts]
        rows = [btns[i:i + 2] for i in range(0, len(btns), 2)]
        await message.answer("🛠 <b>Xizmatlarni boshqarish</b>\n\nTarmoqni tanlang:", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    @dp.callback_query(F.data.startswith("nkam_"))
    async def nk_manage_list(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            return
        _, key, page = callback.data.split("_")
        page = int(page)
        items = sorted(((sid, s) for sid, s in info["nk_services"].items() if nk_platform_of(s) == key),
                       key=lambda x: (x[1].get("category") or "", x[1]["name"]))
        pages = max(1, math.ceil(len(items) / NK_PAGE))
        page = min(max(page, 0), pages - 1)
        rows = [[InlineKeyboardButton(text=f"{'✅' if s.get('enabled', True) else '❌'} {s['name'][:36]}", callback_data=f"nkas_{sid}")]
                for sid, s in items[page * NK_PAGE:(page + 1) * NK_PAGE]]
        nav = []
        if page > 0:
            nav.append(InlineKeyboardButton(text="◀️", callback_data=f"nkam_{key}_{page - 1}"))
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="nknoop"))
        if page < pages - 1:
            nav.append(InlineKeyboardButton(text="▶️", callback_data=f"nkam_{key}_{page + 1}"))
        rows.append(nav)
        rows.append([InlineKeyboardButton(text="✅ Hammasini yoqish", callback_data=f"nkab_{key}_1"),
                     InlineKeyboardButton(text="🚫 Hammasini o'chirish", callback_data=f"nkab_{key}_0")])
        await say(callback, f"{nk_plat_label(key)} — xizmatlar ({len(items)} ta)", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    @dp.callback_query(F.data.startswith("nkab_"))
    async def nk_bulk_toggle(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            return
        _, key, flag = callback.data.split("_")
        n = 0
        for s in info["nk_services"].values():
            if nk_platform_of(s) == key:
                s["enabled"] = flag == "1"
                n += 1
        save_data()
        await callback.answer(f"{n} ta xizmat {'yoqildi' if flag == '1' else 'oʻchirildi'}", show_alert=True)

    def svc_admin_card(sid: str):
        s = info["nk_services"][sid]
        src = "🔌 Panel" if s.get("source") == "panel" else "✋ Qo'lda"
        text = (f"🛠 <b>{esc(s['name'])}</b>\n\n🆔 ID: <code>{sid}</code> · {src}\n📂 {esc(s.get('category') or '')}\n"
                f"💵 Sotuv narxi: <b>{som(price_1000(s))}</b> so'm/1000"
                f"{' (qoʻlda belgilangan)' if s.get('custom_price') is not None else ''}\n"
                f"📉 {int(s['min']):,} – {int(s['max']):,}\n📌 Holati: {'✅ yoqilgan' if s.get('enabled', True) else '❌ oʻchirilgan'}")
        rows = [
            [InlineKeyboardButton(text="🔁 Yoqish / o'chirish", callback_data=f"nkat_{sid}")],
            [InlineKeyboardButton(text="✏️ Narxni belgilash", callback_data=f"nkap_{sid}"),
             InlineKeyboardButton(text="♻️ Narxni tiklash", callback_data=f"nkar_{sid}")],
        ]
        if s.get("source") == "manual":
            rows.append([InlineKeyboardButton(text="🗑 Xizmatni o'chirish", callback_data=f"nkad_{sid}")])
        rows.append([InlineKeyboardButton(text="⬅️ Ro'yxat", callback_data=f"nkam_{nk_platform_of(s)}_0")])
        return text, InlineKeyboardMarkup(inline_keyboard=rows)

