    # ---- narx va umumiy sozlamalar (generic)
    def settings_text(keys_num, title) -> str:
        lines = [f"{title}\n"]
        for k, label in keys_num.items():
            lines.append(f"{label}: <b>{S[k]}</b>")
        return "\n".join(lines)

    def settings_kb(keys, with_extra=False):
        rows = [[InlineKeyboardButton(text=label, callback_data=f"nkset_{k}")] for k, label in keys.items()]
        if with_extra:
            rows.append([InlineKeyboardButton(text=f"🛠 Texnik rejim: {'✅ yoqilgan' if S.get('maintenance') else '❌ oʻchiq'}",
                                              callback_data="nkset_maintenance")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

