    @dp.message(NkAdm.bal_uid, F.text)
    async def nk_bal_uid_in(message: Message, state: FSMContext):
        try:
            uid = int(message.text.strip())
        except ValueError:
            await message.answer("❌ Faqat raqam (ID) kiriting.")
            return
        if uid not in info["users"]:
            await message.answer("❌ Bunday foydalanuvchi botdan foydalanmagan.")
            return
        await state.update_data(uid=uid)
        await state.set_state(NkAdm.bal_amount)
