    def user_card(uid: int):
        orders = [o for o in info["nk_orders"].values() if o["uid"] == uid]
        blocked = uid in info["nk_blocked"]
        text = (f"👤 <b>{esc(info['nk_names'].get(str(uid), 'Nomaʻlum'))}</b>\n🆔 <code>{uid}</code>\n"
                f"💰 Balans: {som(bal(uid))} so'm\n🛒 Sarflagan: {som(info['nk_spent'].get(str(uid), 0))} so'm\n"
                f"📦 Buyurtmalar: {len(orders)}\n👥 Taklif qilgan: {sum(1 for v in info['nk_ref_by'].values() if v == uid)}\n"
                f"🚫 Bloklangan: {'ha' if blocked else 'yoʻq'}")
        kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
            text="✅ Blokdan chiqarish" if blocked else "🚫 Bloklash", callback_data=f"nkub_{uid}")]])
        return text, kb

    @dp.message(NkAdm.find_user, F.text)
    async def nk_find_user_in(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        q = message.text.strip().lower()
        await state.clear()
        found = []
        if q.lstrip("-").isdigit() and int(q) in info["users"]:
            found = [int(q)]
        else:
            for uid_s, nm in info["nk_names"].items():
                if q.lstrip("@") in nm.lower():
                    found.append(int(uid_s))
        if not found:
            await message.answer("😔 Foydalanuvchi topilmadi.")
            return
        if len(found) == 1:
            text, kb = user_card(found[0])
            await message.answer(text, reply_markup=kb)
            return
        rows = [[InlineKeyboardButton(text=f"{info['nk_names'].get(str(u), u)[:30]} ({u})", callback_data=f"nkuv_{u}")] for u in found[:15]]
        await message.answer(f"Topildi: {len(found)} ta (15 tasi ko'rsatildi)", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

