    @dp.message(Command("stats"))
    @dp.message(F.text == "📊 Statistika")
    async def mg_stats(message: Message):
        if not is_adm(message):
            return
        users = mg_users(info)
        now = _time.time()
        day = sum(1 for u in users.values() if now - u.get("la", 0) < 86400)
        week = sum(1 for u in users.values() if now - u.get("la", 0) < 7 * 86400)
        total = sum(u.get("t", 0) for u in users.values())
        bal = sum(u.get("c", 0) for u in users.values())
        taps = sum(u.get("taps", 0) for u in users.values())
        banned = sum(1 for u in users.values() if u.get("b"))
        refs = sum(1 for u in users.values() if u.get("rf"))
        await message.answer(
            "📊 <b>Statistika</b>\n\n"
            f"👥 O'yinchilar: {len(users)} (botda: {len(info['users'])})\n🟢 24 soatda faol: {day}\n📆 7 kunda faol: {week}\n"
            f"👆 Jami bosishlar: {som(taps)}\n🪙 Jami yig'ilgan: {som(total)}\n💰 Qo'ldagi balans: {som(bal)}\n"
            f"👥 Taklif orqali kelganlar: {refs}\n📋 Vazifalar: {len(info['mg_tasks'])}\n🚫 Bloklangan: {banned}\n"
            f"🌐 O'yin manzili: {'✅ sozlangan' if game_url() else '❌ MINIAPP_URL / RAILWAY_PUBLIC_DOMAIN kerak'}")

