        ttype = callback.data[5:]
        await state.update_data(ttype=ttype)
        await state.set_state(MgAdm.task_target)
        if ttype == "channel":
            await callback.message.answer("Kanal usernameni yuboring (masalan: @mening_kanalim).\n⚠️ Bot o'sha kanalda ADMIN bo'lishi shart!")
