    @dp.message(MgAdm.task_target, F.text)
    async def mg_task_target_in(message: Message, state: FSMContext):
        if not is_adm(message):
            return
        d = await state.get_data()
        raw = message.text.strip()
        tid = "k" + uuid.uuid4().hex[:6]
        if d.get("ttype") == "channel":
            try:
                chat = await message.bot.get_chat(raw if raw.startswith("@") else "@" + raw.lstrip("@").replace("https://t.me/", ""))
            except Exception as e:
                await message.answer(f"❌ Kanal topilmadi: {esc(str(e)[:200])}")
                return
            uname = getattr(chat, "username", None)
            if not uname:
                await message.answer("❌ Kanalning ommaviy username'i bo'lishi kerak.")
                return
            info["mg_tasks"][tid] = {"title": d["title"], "reward": d["reward"], "type": "channel", "chat": chat.id, "url": f"https://t.me/{uname}"}
            warn = ""
            try:
                bm = await message.bot.get_chat_member(chat.id, message.bot.id)
                if bm.status not in ("administrator", "creator"):
                    warn = "\n⚠️ Bot kanalda ADMIN emas — obunani tekshira olmaydi!"
            except Exception:
                warn = "\n⚠️ Bot kanalda ADMIN ekanligini tekshira olmadim — admin qilib qo'ying!"
            await message.answer(f"✅ Vazifa qo'shildi: {esc(d['title'])}{warn}", reply_markup=admin_kb())
        else:
            url = raw if raw.startswith(("http://", "https://")) else "https://" + raw
            info["mg_tasks"][tid] = {"title": d["title"], "reward": d["reward"], "type": "link", "url": url}
            await message.answer(f"✅ Vazifa qo'shildi: {esc(d['title'])}", reply_markup=admin_kb())
        save_data()
        await state.clear()

    # ---- sozlamalar
    def settings_text() -> str:
        lines = ["⚙️ <b>O'yin sozlamalari</b>\n"]
        for k, label in MG_SET_NUM.items():
            lines.append(f"{label}: <b>{som(cfg[k])}</b>")
        for k, label in MG_SET_TXT.items():
            v = cfg[k]
            lines.append(f"{label}: <b>{esc(str(v)[:40]) if v else '—'}</b>")
        lines.append(f"🛠 Texnik rejim: <b>{'yoqilgan' if cfg['maintenance'] else 'ʻchiq'}</b>")
        return "\n".join(lines)

    def settings_kb():
        rows = [[InlineKeyboardButton(text=label, callback_data=f"mgs_{k}")] for k, label in {**MG_SET_NUM, **MG_SET_TXT}.items()]
        rows.append([InlineKeyboardButton(text="🛠 Texnik rejimni almashtirish", callback_data="mgs_maintenance")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    @dp.message(F.text == "⚙️ O'yin sozlamalari")
    async def mg_settings(message: Message, state: FSMContext):
        if not is_adm(message):
            return
        await state.clear()
        await message.answer(settings_text(), reply_markup=settings_kb())

    @dp.callback_query(F.data.startswith("mgs_"))
    async def mg_setting_pick(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            return
        key = callback.data[4:]
        if key == "maintenance":
            cfg["maintenance"] = not cfg["maintenance"]
            save_data()
            await callback.answer("Texnik rejim " + ("yoqildi" if cfg["maintenance"] else "o'chirildi"), show_alert=True)
            return
        if key not in MG_SET_NUM and key not in MG_SET_TXT:
            await callback.answer()
            return
        await state.set_state(MgAdm.set_value)
        await state.update_data(key=key)
        label = MG_SET_NUM.get(key) or MG_SET_TXT.get(key)
        hint = "Yangi qiymatni yozing:" if key in MG_SET_NUM else "Yangi matnni yozing (standartga qaytarish uchun «-»):"
        await callback.message.answer(f"{label}\nJoriy: <b>{esc(str(cfg[key]) or '—')}</b>\n\n{hint}")
        await callback.answer()

    @dp.message(MgAdm.set_value, F.text)
    async def mg_setting_in(message: Message, state: FSMContext):
        if not is_adm(message):
            return
        d = await state.get_data()
        key = d.get("key")
        raw = message.text.strip()
        if key in MG_SET_NUM:
            try:
                v = int(raw.replace(" ", ""))
                assert 0 <= v <= 1_000_000_000
                if key in ("max_tps", "offline_hours"):
                    assert v >= 1
                if key == "max_tps":
                    assert v <= 60
            except Exception:
                await message.answer("❌ To'g'ri butun son kiriting.")
                return
            cfg[key] = v
        elif key in MG_SET_TXT:
            if raw == "-":
                cfg[key] = MG_CFG_DEFAULT[key]
            else:
                if key == "welcome":
                    prob = _html_problem(raw)
                    if prob:
                        await message.answer(f"❌ HTML xatosi: {prob}")
                        return
                cfg[key] = raw[:200 if key != "welcome" else 1500]
        else:
            await state.clear()
            return
        save_data()
        await state.clear()
        await message.answer("✅ Saqlandi.\n\n" + settings_text(), reply_markup=settings_kb())

