    def user_card(uid: int):
        u = mg_users(info)[str(uid)]
        lg = mg_league(u["t"])[0]
        text = (f"👤 <b>{esc(u['n'])}</b> {('@' + esc(u['un'])) if u.get('un') else ''}\n🆔 <code>{uid}</code>\n"
                f"💰 Balans: {som(u['c'])}\n📈 Jami: {som(u['t'])} · {lg}\n👆 Bosishlar: {som(u.get('taps', 0))}\n"
                f"🔧 Daraja: tap {u['tp']} · energiya {u['el']} · tiklanish {u['rl']} · mining {u['ml']}\n"
                f"👥 Takliflar: {u.get('rc', 0)}\n🚫 Bloklangan: {'ha' if u.get('b') else 'yo‘q'}")
        kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
            text="✅ Blokdan chiqarish" if u.get("b") else "🚫 Bloklash", callback_data=f"mgub_{uid}")]])
        return text, kb

