    @dp.message(MgAdm.find_user, F.text)
    async def mg_find_in(message: Message, state: FSMContext):
        if not is_adm(message):
            return
        q = message.text.strip().lower().lstrip("@")
        await state.clear()
        users = mg_users(info)
        found = [int(k) for k, u in users.items() if k == q or q in (u.get("n") or "").lower() or q in (u.get("un") or "").lower()]
        if not found:
            await message.answer("😔 O'yinchi topilmadi.")
            return
        if len(found) == 1:
            text, kb = user_card(found[0])
            await message.answer(text, reply_markup=kb)
            return
        rows = [[InlineKeyboardButton(text=f"{users[str(f)]['n'][:28]} ({f})", callback_data=f"mguv_{f}")] for f in found[:15]]
        await message.answer(f"Topildi: {len(found)} ta (15 tasi ko'rsatildi)", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

