    @dp.callback_query(F.data == "mgbc_yes")
    async def mg_broadcast_yes(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            return
        d = await state.get_data()
        await state.clear()
        if not d.get("mid"):
            await callback.answer("Xabar topilmadi", show_alert=True)
            return
        await callback.answer("Yuborilmoqda...")
        ok = fail = 0
        for uid in list(info["users"]):
            try:
                await callback.bot.copy_message(uid, d["chat_id"], d["mid"])
                ok += 1
            except Exception:
                fail += 1
            await asyncio.sleep(0.05)
        await callback.message.answer(f"📢 <b>E'lon yakunlandi</b>\n✅ Yetkazildi: {ok}\n❌ Yetkazilmadi: {fail}")

    @dp.message(F.text == "📤 Eksport")
    async def mg_export(message: Message):
        if not is_adm(message):
            return
        buf = ["id,ism,username,balans,jami,bosishlar,tap,energiya,tiklanish,mining,takliflar,bloklangan,qoshilgan"]
        for k, u in mg_users(info).items():
            nm = str(u.get("n", "")).replace(",", " ").replace("\n", " ")
            buf.append(f"{k},{nm},{u.get('un', '')},{int(u['c'])},{int(u['t'])},{u.get('taps', 0)},{u['tp']},{u['el']},{u['rl']},{u['ml']},{u.get('rc', 0)},{int(bool(u.get('b')))},{u.get('jn', '')}")
        await message.answer_document(BufferedInputFile("\n".join(buf).encode("utf-8-sig"), filename="oyinchilar.csv"),
                                      caption=f"📤 {len(mg_users(info))} ta o'yinchi")

    # ---------------------------------------------------------------- ishga tushirish
    async def mg_on_startup(bot: Bot):
        try:
            me = await bot.me()
            info["mg_botname"] = me.username or ""
        except Exception as e:
            logging.info(f"Mini App: bot nomini olib bo'lmadi: {e}")
        url = game_url()
        if url:
            try:
                await bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="🎮 O'ynash", web_app=WebAppInfo(url=url)))
            except Exception as e:
                logging.info(f"Mini App menyu tugmasi ({token[-6:]}): {e}")
        else:
            logging.warning("Mini App bot: MINIAPP_URL yoki RAILWAY_PUBLIC_DOMAIN topilmadi — o'yin tugmasi ishlamaydi.")
        t = _MG_STATE.get("task")
        if not t or t.done():
            _MG_STATE["task"] = asyncio.create_task(mg_saver_loop())

    dp.startup.register(mg_on_startup)


