def get_global_button_rows():
    rows = [[KeyboardButton(text="◀️ Orqaga")]]
    rows += [[KeyboardButton(text=b["label"])] for b in data.get("global_buttons", [])]
    return rows


def is_global_button_text(message: Message) -> bool:
    if not message.text:
        return False
    return any(message.text == b["label"] for b in data.get("global_buttons", []))


def setup_global_buttons_handler(dp: Dispatcher, start_func=None):
    @dp.message(F.text == "◀️ Orqaga")
    async def back_button_handler(message: Message, state: FSMContext):
        await state.clear()
        if start_func:
            await start_func(message, state)
        else:
            await message.answer("🏠 Bosh menyuga qaytish uchun /start bosing.")

    @dp.message(is_global_button_text)
    async def global_button_handler(message: Message):
        for b in data.get("global_buttons", []):
            if b["label"] == message.text:
                await message.answer(b["response"])
                return


async def start_child_bot(token: str, bot_type: str):
    if token in running_bots:
        return
    if bot_type not in SETUP_FUNCTIONS:
        logging.error(
            f"'{bot_type}' turidagi bot ishga tushirilmadi (token: ...{token[-6:]}) — "
            "bu bot turi endi platformada mavjud emas."
        )
        return
    child_bot = Bot(token=token, default=DefaultBotProperties(parse_mode=ParseMode.HTML))
    if bot_type in KINO_TYPES:
        # Tartib muhim: avval rang (asl o'zbekcha matn bo'yicha), keyin tarjima
        child_bot.session.middleware(kino_btn_style_middleware)
        child_bot.session.middleware(kino_i18n_request_middleware)
    else:
        child_bot.session.middleware(auto_style_request_middleware)
    try:
        await child_bot.delete_webhook(drop_pending_updates=False)
    except Exception as e:
        logging.error(f"delete_webhook xatosi ({token[-6:]}): {e}")
    child_dp = Dispatcher(storage=MemoryStorage())
    install_edit_in_place(child_dp)
    child_dp.update.outer_middleware(BotMetricsMiddleware(token))
    SETUP_FUNCTIONS[bot_type](child_dp, token)
    if bot_type in ("kino_pro",):
        _kinfo = data["bots"].get(token, {})
        _kurl = get_kinopanel_url(_kinfo.get("id"))
        if _kurl:
            for _aid in _kinfo.get("admin_ids", [_kinfo.get("admin_id")]):
                try:
                    await child_bot.set_chat_menu_button(
                        chat_id=_aid,
                        menu_button=MenuButtonWebApp(text="Panel", web_app=WebAppInfo(url=_kurl)),
                    )
                except Exception as e:
                    logging.info(f"Kino panel menyu tugmasi ({token[-6:]}, admin {_aid}): {e}")
    task = asyncio.create_task(child_dp.start_polling(child_bot))
    running_bots[token] = task


AUTO_DELETE_GRACE_DAYS = 7      # sinov tugagach to'lov bo'lmasa, bot yana shuncha kun saqlanadi, so'ng dasturdan butunlay o'chiriladi (jami 2 hafta)
AUTO_DELETE_AMNESTY_DAYS = 2    # funksiya birinchi yoqilganda muddati allaqachon o'tgan botlarga beriladigan minimal ogohlantirish muddati


def _trial_expiry_unpaid(info: dict):
    """Faqat standart sinovli va hali hech qachon to'lanmagan botlar uchun sinov tugash vaqti, aks holda None.
    (Platforma adminlari botlari, to'lov qilgan botlar, sinovsiz botlar o'chirilmaydi.)"""
    if is_full_admin(info.get("admin_id")):
        return None
    if info.get("paid_until") or info.get("skip_trial"):
        return None
    trial_cfg = get_trial_config(info.get("type"))
    if not trial_cfg.get("enabled", True):
        return None
    try:
        return datetime.fromisoformat(info["created_at"]) + timedelta(days=trial_cfg.get("days", TRIAL_DAYS))
    except Exception:
        return None


async def auto_delete_unpaid_bots():
    """Sinov muddati tugab, yana AUTO_DELETE_GRACE_DAYS kun ichida ham to'lov qilinmagan botlarni dasturdan butunlay o'chiradi.
    O'chirishdan ~1 kun oldin egasiga ogohlantirish yuboriladi (ogohlantirilmagan bot o'chirilmaydi)."""
    now = datetime.now()
    started = data.get("auto_delete_started")
    try:
        started_dt = datetime.fromisoformat(started) if started else None
    except Exception:
        started_dt = None
    if started_dt is None:
        started_dt = now
        data["auto_delete_started"] = now.isoformat()
        save_data()
    floor = started_dt + timedelta(days=AUTO_DELETE_AMNESTY_DAYS)

    to_delete = []
    changed = False
    for token, info in list(data["bots"].items()):
        exp = _trial_expiry_unpaid(info)
        if exp is None:
            continue
        deadline = max(exp + timedelta(days=AUTO_DELETE_GRACE_DAYS), floor)
        left_days = (deadline - now).total_seconds() / 86400
        if left_days > 1:
            continue
        warned_at = info.get("delete_warned_at")
        if not warned_at:
            amount = next_payment_amount(info)
            try:
                await main_bot.send_message(
                    info["admin_id"],
                    f"⚠️ <b>Botingiz o'chirilish arafasida!</b>\n\n"
                    f"{BOT_TYPES.get(info['type'])} (<b>{html_escape(str(info.get('name', '')))}</b>) uchun sinov muddati tugagan va to'lov qilinmagan.\n\n"
                    f"⏳ <b>24 soat ichida</b> to'lov qilinmasa, bot barcha ma'lumotlari bilan dasturdan butunlay o'chiriladi.\n\n"
                    f"Davom ettirish uchun: <b>{amount:,} so'm/oy</b>. «💰 Hisob to'ldirish» orqali balansni to'ldiring yoki administrator bilan bog'laning.",
                    reply_markup=contact_admin_kb(),
                )
            except Exception as e:
                logging.error(f"O'chirish ogohlantirishi yuborilmadi ({token}): {e}")
            info["delete_warned_at"] = now.isoformat()
            changed = True
            continue
        try:
            warned_dt = datetime.fromisoformat(warned_at)
        except Exception:
            warned_dt = now
        if left_days <= 0 and now - warned_dt >= timedelta(hours=18):
            to_delete.append((token, info))

    deleted_lines = []
    for token, info in to_delete:
        task = running_bots.pop(token, None)
        if task:
            task.cancel()
        data["bots"].pop(token, None)
        rec = {"id": info.get("id"), "name": info.get("name"), "type": info.get("type"),
               "owner": info.get("admin_id"), "date": now.strftime("%Y-%m-%d %H:%M")}
        data.setdefault("auto_deleted_bots", []).append(rec)
        data["auto_deleted_bots"] = data["auto_deleted_bots"][-200:]
        deleted_lines.append(f"• {html_escape(str(rec['name']))} ({BOT_TYPES.get(rec['type'], rec['type'])}) — <code>{rec['owner']}</code>")
        changed = True
        try:
            await main_bot.send_message(
                info["admin_id"],
                f"🗑 <b>{html_escape(str(info.get('name', '')))}</b> boti sinov muddati tugagach {AUTO_DELETE_GRACE_DAYS} kun ichida to'lov qilinmagani uchun dasturdan o'chirildi.\n\n"
                "Yangi bot yaratish uchun «🤖 Bot yaratish» tugmasini bosing.",
            )
        except Exception as e:
            logging.info(f"O'chirilgan bot egasiga xabar yuborilmadi ({token}): {e}")
    if changed:
        save_data()
    if deleted_lines:
        try:
            await main_bot.send_message(ADMIN_ID, "🗑 <b>Avtomatik o'chirilgan botlar</b> (to'lov qilinmagan):\n" + "\n".join(deleted_lines))
        except Exception:
            pass
        logging.info(f"Avtomatik o'chirilgan botlar: {len(deleted_lines)} ta")


async def trial_warning_loop():
    """Har 6 soatda barcha botlarni tekshirib, sinov/to'lov muddati tugashiga 1 kun qolganlarga ogohlantirish yuboradi."""
    while True:
        try:
            today = datetime.now().strftime("%Y-%m-%d")
            for token, info in data["bots"].items():
                if info.get("paid_until"):
                    expiry = datetime.fromisoformat(info["paid_until"])
                    kind = "to'lov"
                else:
                    trial_cfg = get_trial_config(info.get("type"))
                    if not trial_cfg.get("enabled", True):
                        continue  # Bu turdagi bot uchun sinov yo'q — ogohlantirish shart emas
                    expiry = datetime.fromisoformat(info["created_at"]) + timedelta(days=trial_cfg.get("days", TRIAL_DAYS))
                    kind = "sinov"

                days_left = (expiry - datetime.now()).total_seconds() / 86400
                if 0 <= days_left <= 1 and info.get("last_warned_date") != today:
                    amount = next_payment_amount(info)
                    try:
                        await main_bot.send_message(
                            info["admin_id"],
                            f"⏳ <b>Ogohlantirish!</b>\n\n"
                            f"{BOT_TYPES.get(info['type'])} (<b>{info['name']}</b>) uchun {kind} muddati "
                            f"taxminan 1 kundan keyin tugaydi.\n\n"
                            f"Davom ettirish uchun to'lov: <b>{amount:,} so'm</b>.\n"
                            "To'lovni amalga oshirish uchun administrator bilan bog'laning.",
                            reply_markup=contact_admin_kb(),
                        )
                    except Exception as e:
                        logging.error(f"Ogohlantirish yuborishda xato ({token}): {e}")
                    info["last_warned_date"] = today
                    save_data()

                if info.get("type") in KINO_TYPES and info.get("auto_report_enabled"):
                    now = datetime.now()
                    if now.hour >= info.get("auto_report_hour", 9) and info.get("last_report_date") != today:
                        try:
                            await main_bot.send_message(info["admin_id"], build_kino_report(info))
                        except Exception as e:
                            logging.error(f"Avtomatik hisobot yuborishda xato ({token}): {e}")
                        info["last_report_date"] = today
                        save_data()
            await auto_delete_unpaid_bots()
        except Exception as e:
            logging.error(f"trial_warning_loop xatosi: {e}")

        await asyncio.sleep(6 * 60 * 60)  # 6 soat


async def topup_nudge_loop():
    """Har kuni (Toshkent vaqti bilan NUDGE_HOUR dan keyin) hisobini hali to'ldirmagan barcha
    foydalanuvchilarga «Botingiz deyarli tayyor edi» eslatmasini yuboradi.
    Foydalanuvchi hisobini to'ldirgach (balansi yozuvi paydo bo'lgach) eslatma o'zi to'xtaydi."""
    from datetime import timezone
    from aiogram.exceptions import TelegramRetryAfter
    tz = timezone(timedelta(hours=5))   # O'zbekiston (UTC+5)
    hour = int(os.getenv("NUDGE_HOUR", "12"))
    data.setdefault("nudge_state", {"date": "", "done": []})
    data.setdefault("nudge_blocked", [])
    while True:
        try:
            now = datetime.now(tz)
            today = now.strftime("%Y-%m-%d")
            st = data["nudge_state"]
            if st.get("date") != today:
                st["date"] = today
                st["done"] = []
                save_data()
            if now.hour >= hour:
                admins = {ADMIN_ID, *data["full_admins"]}
                done = set(st["done"])
                blocked = set(data["nudge_blocked"]) | set(data.get("blocked_users", []))
                sent = 0
                for uid in list(data["platform_users"]):
                    if uid in done or uid in admins or uid in blocked:
                        continue
                    if str(uid) in data["user_balances"]:      # hisobini to'ldirgan — eslatma shart emas
                        continue
                    kb = InlineKeyboardMarkup(inline_keyboard=[
                        [InlineKeyboardButton(text="➕ Davom ettirish", callback_data="nudge_continue")]
                    ])
                    for attempt in range(2):
                        try:
                            await main_bot.send_message(uid, T("topup_nudge"), reply_markup=kb)
                            sent += 1
                            break
                        except TelegramRetryAfter as e:
                            await asyncio.sleep(e.retry_after + 1)
                        except TelegramForbiddenError:
                            data["nudge_blocked"].append(uid)
                            break
                        except Exception as e:
                            logging.warning(f"Kunlik eslatma yuborilmadi ({uid}): {e}")
                            break
                    st["done"].append(uid)
                    if len(st["done"]) % 20 == 0:
                        save_data()
                    await asyncio.sleep(0.05)   # Telegram limiti (~30 xabar/soniya) dan oshmaslik uchun
                save_data()
                if sent:
                    logging.info(f"Kunlik eslatma yuborildi: {sent} ta foydalanuvchi")
        except Exception as e:
            logging.error(f"topup_nudge_loop xatosi: {e}")
        await asyncio.sleep(30 * 60)   # har 30 daqiqada tekshiradi


def build_kino_report(info: dict) -> str:
    now = datetime.now()
    today = now.strftime("%Y-%m-%d")
    daily_usage = info.get("daily_usage", {})
    today_count = len(daily_usage.get("users", [])) if daily_usage.get("date") == today else 0
    active_vip = 0
    for u in info.get("premium_users", {}).values():
        try:
            if datetime.fromisoformat(u["until"]) > now:
                active_vip += 1
        except Exception:
            pass
    return (
        f"📅 <b>Kunlik hisobot — {info['name']}</b>\n\n"
        f"👥 Jami foydalanuvchilar: {len(info.get('users', []))}\n"
        f"📊 Bugungi faol foydalanuvchilar: {today_count}\n"
        f"🔍 Jami so'rovlar: {info.get('stats', {}).get('requests', 0)}\n"
        f"🎞 Kontent soni: {len(info.get('movies', {}))}\n"
        f"💎 Faol VIP: {active_vip}\n"
        f"👁 Bugungi ko'rishlar: {info.get('daily_views', {}).get(today, 0)}\n"
        f"💰 Bugungi tushum: {sum(int(p.get('amount', 0) or 0) for p in info.get('payment_log', []) if str(p.get('date', '')).startswith(today)):,} so'm"
    )




